#nullable enable

using Marten;
using Wolverine;
using Allocation.Automation;
using Allocation.Contracts;
using Wolverine.Http;

namespace Allocation.Slices.Allocation;

/// <summary>
/// STEP ONE of the two-step workflow, over HTTP because a person asks for it.
///
/// The endpoint is thin on purpose — the mechanism is in <see cref="SlotReservation"/>, which the race
/// tests call directly. What lives here is the one thing that is genuinely about the WEB REQUEST, and it
/// is the book's most quotable sentence about this pattern:
///
///   > "Although it is modeled as Event, Read Model and Processor — the whole cycle of reservation and
///   >  execution can be done within one single web-request."
///
/// So when the chosen execution mode is in-request, this endpoint runs step two before it answers. That is
/// not a shortcut around the model: the trigger still runs, still reads its todo View, still issues
/// IssueGrant, and the compensation still runs if the work refuses. The ONLY thing that changed is what
/// wakes it — which is the same freedom the automation folder measures four times over, with the request
/// itself as a fifth mechanism the model equally does not constrain.
///
/// WHAT IT COSTS is in the README's table, and the short version is: no daemon and no wakeup to get wrong,
/// paid for with a caller who waits for the work, and with NO RECOVERY if the process dies between the two
/// commits. Out-of-request keeps the pending row and recovers; in-request has nothing to recover from
/// because nothing recorded that there was work to do.
/// </summary>
public static class ReserveSlotEndpoint
{
    public const string Route = "/pools/{poolId}/reservations";

    /// <summary>
    /// The reservation the caller got. A journey test must use THESE values rather than ones it made up,
    /// or it cannot see a slice that echoes something subtly different — and here the slot number is
    /// something the caller could not have known, so there is nothing else to use.
    /// </summary>
    public sealed record Reserved(Guid PoolId, int SlotNumber, Guid GrantId);

    [WolverinePost(Route)]
    public static async Task<IResult> Reserve(
        Guid poolId,
        ReserveSlot command,
        IDocumentStore store,
        IMessageBus bus,
        CancellationToken cancellation)
    {
        // terminal="grantId:generated" — the handler mints it. Honouring a supplied one is what lets a
        // test name the grant it is talking about, which is the same accommodation automation/ needed and
        // for the same reason: without it, tests cannot be independent of each other.
        var grantId = command.GrantId == Guid.Empty ? Guid.NewGuid() : command.GrantId;

        var result = await SlotReservation.Reserve(store, poolId, grantId, cancellation);

        if (!result.Outcome.Accepted)
            return Results.Problem(
                title: result.Outcome.Error,
                detail: result.Outcome.Detail,
                statusCode: StatusCodes.Status400BadRequest);

        // THE WHOLE CYCLE IN ONE REQUEST, when that is the chosen mode. Two commits, not one — and that
        // distinction is the point rather than a detail. One transaction spanning both steps would make
        // the reservation pointless: if reserve and execute can be atomic, there is nothing to reserve
        // AGAINST. The pattern exists precisely where they cannot be, so this runs them in order and
        // compensates, in the same request, rather than pretending they are one write.
        if (IssueGrantWakeup.Chosen == IssueGrantWakeup.Mechanism.InRequest)
        {
            await bus.InvokeAsync(new RunIssueGrant(), cancellation);
            await bus.InvokeAsync(new RunReleaseSlot(), cancellation);
        }

        var reserved = result.Reserved!;
        return Results.Ok(new Reserved(reserved.PoolId, reserved.SlotNumber, reserved.GrantId));
    }
}
